static int maxFenster(int[] n, int k) {
    if (k < 1 || k > n.length) throw new IllegalArgumentException();
    int summe = 0;
    for (int i = 0; i < k; i++) summe += n[i];
    int best = summe;
    for (int i = k; i < n.length; i++) {
        summe += n[i] - n[i - k];
        best = Math.max(best, summe);
    }
    return best;
}

static int maxTeil(int[] n) {
    if (n.length == 0) throw new IllegalArgumentException();
    int aktuell = n[0], best = n[0];
    for (int i = 1; i < n.length; i++) {
        aktuell = Math.max(n[i], aktuell + n[i]);
        best = Math.max(best, aktuell);
    }
    return best;
}

static int ggt(int a, int b) {
    if (a < 0 || b < 0 || (a == 0 && b == 0)) throw new IllegalArgumentException();
    while (b != 0) { int rest = a % b; a = b; b = rest; }
    return a;
}

static int fib(int n) {
    if (n < 0 || n > 46) throw new IllegalArgumentException();
    if (n < 2) return n;
    int[] dp = new int[n + 1]; dp[1] = 1;
    for (int i = 2; i <= n; i++) dp[i] = dp[i - 1] + dp[i - 2];
    return dp[n];
}

