static void einfuegenSort(int[] n) {
    for (int i = 1; i < n.length; i++) {
        int wert = n[i], j = i - 1;
        while (j >= 0 && n[j] > wert) { n[j + 1] = n[j]; j--; }
        n[j + 1] = wert;
    }
}

static int lowerBound(int[] n, int ziel) {
    int links = 0, rechts = n.length;
    while (links < rechts) {
        int mitte = links + (rechts - links) / 2;
        if (n[mitte] < ziel) links = mitte + 1; else rechts = mitte;
    }
    return links;
}

static int distanz(int[][] m, int start, int ziel) {
    int[] d = new int[m.length]; boolean[] fertig = new boolean[m.length];
    Arrays.fill(d, Integer.MAX_VALUE); d[start] = 0;
    for (int r = 0; r < m.length; r++) {
        int u = -1;
        for (int i = 0; i < m.length; i++) if (!fertig[i] && (u < 0 || d[i] < d[u])) u = i;
        if (u < 0 || d[u] == Integer.MAX_VALUE) break;
        fertig[u] = true;
        for (int v = 0; v < m.length; v++)
            if (!fertig[v] && m[u][v] >= 0) d[v] = Math.min(d[v], Math.addExact(d[u], m[u][v]));
    }
    return d[ziel];
}

static List<Integer> reihenfolge(List<List<Integer>> g) {
    int[] grad = new int[g.size()];
    for (var nachbarn : g) for (int v : nachbarn) grad[v]++;
    var q = new ArrayDeque<Integer>(); var out = new ArrayList<Integer>();
    for (int i = 0; i < grad.length; i++) if (grad[i] == 0) q.offer(i);
    while (!q.isEmpty()) {
        int u = q.poll(); out.add(u);
        for (int v : g.get(u)) if (--grad[v] == 0) q.offer(v);
    }
    if (out.size() != g.size()) throw new IllegalArgumentException("Zyklus");
    return out;
}

